for b, c in np.ndindex(batch_size, n_class):
    (edges_pred, edges_gt) = get_mask_edges(y_pred[b, c], y[b, c], crop=False)
    if not np.any(edges_gt):
        warnings.warn(f"the ground truth of class {c} is all 0, this may result in nan/inf distance.")
    if not np.any(edges_pred):
        warnings.warn(f"the prediction of class {c} is all 0, this may result in nan/inf distance.")

    if spacing_list[b] is not None and distance_metric == "euclidean":
        # physical-spacing measurement: the boundary of each sampled mask is interpreted
        # physically (halfway between neighboring foreground and background samples), and both
        # the within-tolerance part and the total boundary are measured with the physical
        # surface measure of the samples, see `get_edge_surface_distance`.
        distances_pred_gt, areas_pred = get_edge_surface_distance(
            edges_pred, y[b, c], distance_metric=distance_metric, spacing=spacing_list[b]
        )
        distances_gt_pred, areas_gt = get_edge_surface_distance(
            edges_gt, y_pred[b, c], distance_metric=distance_metric, spacing=spacing_list[b]
        )

        boundary_complete = float(areas_pred.sum() + areas_gt.sum())
        boundary_correct = float(
            areas_pred[distances_pred_gt <= class_thresholds[c]].sum()
            + areas_gt[distances_gt_pred <= class_thresholds[c]].sum()
        )
    else:
        # legacy unit-grid behavior: distances on the lattice and per-sample counting.
        distances_pred_gt = get_surface_distance(
            edges_pred, edges_gt, distance_metric=distance_metric, spacing=spacing_list[b]
        )
        distances_gt_pred = get_surface_distance(
            edges_gt, edges_pred, distance_metric=distance_metric, spacing=spacing_list[b]
        )

        boundary_complete = len(distances_pred_gt) + len(distances_gt_pred)
        boundary_correct = np.sum(distances_pred_gt <= class_thresholds[c]) + np.sum(
            distances_gt_pred <= class_thresholds[c]
        )

    if boundary_complete == 0:
        # the class is neither present in the prediction, nor in the reference segmentation
        nsd[b, c] = np.nan
    else:
        nsd[b, c] = boundary_correct / boundary_complete

